-- Run after 01-init.sql in the wallet_demo database.
-- Tables are owned by the consumer service role; Hibernate should validate them.
-- UUID account and history IDs are generated by Hibernate.
BEGIN;
SET LOCAL ROLE csmuser;

-- registration_type: Self=0, Management=1
-- status: Applied=0, Approved=1, Rejected=2
CREATE TABLE consumer.account (
    id UUID PRIMARY KEY,
    email VARCHAR(255) NOT NULL UNIQUE,
    name VARCHAR(255),
    phone VARCHAR(255) NOT NULL,
    address VARCHAR(255) NOT NULL,
    date_of_birth DATE NOT NULL,
    registration_type SMALLINT NOT NULL,
    status SMALLINT NOT NULL,
    registered_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    approved_at TIMESTAMP(6) WITH TIME ZONE,
    rejected_at TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT ck_account_registration_type CHECK (registration_type BETWEEN 0 AND 1),
    CONSTRAINT ck_account_status CHECK (status BETWEEN 0 AND 2)
);

-- @MapsId shares the account's UUID through the account_id primary key.
-- status: Login=0, Logout=1
CREATE TABLE consumer.account_access (
    account_id UUID PRIMARY KEY REFERENCES consumer.account (id),
    status SMALLINT NOT NULL,
    status_change_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT ck_account_access_status CHECK (status BETWEEN 0 AND 1)
);

-- AccountAccessPk embeds account_id and revision as a composite primary key.
-- access status: Login=0, Logout=1
CREATE TABLE consumer.access_history (
    account_id UUID NOT NULL REFERENCES consumer.account (id),
    revision INTEGER NOT NULL,
    status SMALLINT NOT NULL,
    status_change_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    PRIMARY KEY (account_id, revision),
    CONSTRAINT ck_access_history_status CHECK (status BETWEEN 0 AND 1)
);

-- @MapsId shares the account's UUID through the account_id primary key.
-- status: Active=0, Locked=1
CREATE TABLE consumer.account_lock_status (
    account_id UUID PRIMARY KEY REFERENCES consumer.account (id),
    status SMALLINT NOT NULL,
    status_change_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT ck_account_lock_status CHECK (status BETWEEN 0 AND 1)
);

-- lock_type: Temporary=0, Permenant=1 (spelling matches the current Java enum).
CREATE TABLE consumer.pin_lock_history (
    id UUID PRIMARY KEY,
    event_id UUID NOT NULL,
    account_id UUID NOT NULL REFERENCES consumer.account (id),
    lock_type SMALLINT NOT NULL,
    lock_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    locked_until TIMESTAMP(6) WITH TIME ZONE,
    requested_by VARCHAR(255),
    CONSTRAINT ck_pin_lock_history_type CHECK (lock_type BETWEEN 0 AND 2),
    CONSTRAINT uk_consumer_pin_lock_history_event UNIQUE (event_id)
);

CREATE INDEX ix_pin_lock_history_account_lock_at
    ON consumer.pin_lock_history (account_id, lock_at);

CREATE TABLE consumer.outbox_event (
    id UUID PRIMARY KEY,
    topic VARCHAR(100) NOT NULL,
    aggregate_key VARCHAR(255) NOT NULL,
    payload TEXT NOT NULL,
    created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    next_attempt_at TIMESTAMP(6) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    claimed_until TIMESTAMP(6) WITH TIME ZONE,
    claim_token UUID,
    published_at TIMESTAMP(6) WITH TIME ZONE,
    attempt_count INTEGER NOT NULL,
    last_error TEXT,
    dead_lettered_at TIMESTAMP(6) WITH TIME ZONE
);

CREATE INDEX ix_consumer_outbox_event_pending
    ON consumer.outbox_event (published_at, dead_lettered_at, next_attempt_at, created_at);

COMMIT;
